<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Wallet | AppTasker</title><style>*{box-sizing:border-box}body{margin:0;background:#f5f7fb;font-family:Inter,system-ui;color:#182230}.w{max-width:940px;margin:auto;padding:24px 16px 70px}.back{color:#526df5;text-decoration:none;font-weight:800}.hero{margin-top:20px;padding:28px;border-radius:22px;background:linear-gradient(125deg,#526df5,#7358f6);color:white;box-shadow:0 15px 35px #526df52a}.hero strong{display:block;font-size:38px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.card{background:#fff;border:1px solid #e7eaf0;border-radius:18px;padding:20px;margin-top:18px}.row{display:flex;justify-content:space-between;gap:12px;padding:14px 0;border-bottom:1px solid #eee}.muted{color:#667085;font-size:13px}.input{width:100%;padding:12px;border:1px solid #d7dce5;border-radius:11px;margin:6px 0}.btn{width:100%;padding:12px;border:0;border-radius:11px;background:#526df5;color:white;font-weight:850;margin-top:7px}.msg{padding:11px;border-radius:10px;background:#ecfdf3;color:#087a48}.err{padding:11px;border-radius:10px;background:#fef3f2;color:#b42318}@media(max-width:700px){.grid{grid-template-columns:1fr}.hero strong{font-size:32px}}</style></head><body><main class="w"><a class="back" href="{{ route('worker.dashboard') }}">← Dashboard</a><section class="hero"><small>Approved earnings</small><strong>৳{{ number_format($balance,2) }}</strong><div>Available to withdraw: ৳{{ number_format($availableBalance,2) }}</div></section><section class="grid"><div class="card"><h2>Earning history</h2>@forelse($approved as $item)<div class="row"><span>{{ $item->task->title }}</span><strong>+৳{{ number_format((float)$item->task->reward,2) }}</strong></div>@empty<p class="muted">No approved earnings yet.</p>@endforelse</div><div class="card"><h2>Withdraw via bKash</h2>@if(session('success'))<p class="msg">{{ session('success') }}</p>@endif @if($errors->any())<p class="err">{{ $er